{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Normalize input item embeddings by their RMS magnitude with epsilon 1e-6 and a jointly learned scalar gain initialized to 1. Preserve zero padding, raw output embeddings, scoring, GRU topology, loss, optimizer, and routing. The predictor imports the updated model class and restores the gain from each category's single checkpoint.",
      "edits": [
        {
          "find": "                 dropout_rate: float = 0.1):\n        super().__init__()",
          "replace": "                 dropout_rate: float = 0.1, input_rms_eps: float = 1e-6):\n        super().__init__()\n        self.input_rms_eps = input_rms_eps\n        self.input_embedding_gain = nn.Parameter(torch.ones(()))"
        },
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.item_emb(seq)\n        inverse_rms = torch.rsqrt(emb.square().mean(dim=-1, keepdim=True) + self.input_rms_eps)\n        emb = emb * inverse_rms * self.input_embedding_gain\n        return emb.masked_fill(seq.eq(0).unsqueeze(-1), 0.0)\n\n    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.input_embeddings(seq))"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.input_embeddings(seq))"
        },
        {
          "find": "            \"dropout_rate\": DROPOUT_RATE,\n        }, f)",
          "replace": "            \"dropout_rate\": DROPOUT_RATE,\n            \"input_rms_eps\": model.input_rms_eps,\n        }, f)"
        },
        {
          "find": "            dropout_rate=0.0,\n        ).to(_device)",
          "replace": "            dropout_rate=0.0,\n            input_rms_eps=meta[\"input_rms_eps\"],\n        ).to(_device)"
        }
      ]
    }
  ],
  "change_summary": "Apply input-only RMS embedding normalization with one learned scalar gain, preserving padding and output scoring. Update checkpoint metadata and the embedded predictor writer for consistent inference."
}
